import { useState } from 'react';

function Results({ range, tips, shifts, onStartAgainBtnClick }) {

    const [results, setResults] = useState([]);

    const { startDate, endDate } = range[0];
    const monthOption = { month: 'long' };
    const dateOption = { day: 'numeric' };
    const month = startDate.toLocaleDateString('en-US', monthOption);
    const formattedStartDate = startDate.toLocaleDateString('en-US', dateOption);
    const formattedEndDate = endDate.toLocaleDateString('en-US', dateOption);

    function calculateTips(tips, shifts) {
        for (let tip in tips) {
            // Divide tip by percentage
            const morningTip = tip.morningTip * 0.6;
            // Calculate total morning hours for a corresponding date
            let totalHours = 0;
            shifts.filter((shift) => shift.date === tip.date).map((shift) => totalHours + shift.morningHours);
