    }


    return (
        <div className="wrapper">
            <button className='button' onClick={onStartAgainBtnClick}>Start again</button>
            <div className="results-container">
                <p>
                    From {month} {formattedStartDate} to {formattedEndDate}
                </p>
            </div>
        </div>
    );
}

export default Results;
